import React from 'react';

import { QuarterKey } from 'utils/timePeriod/timePeriodAvailability';

import { QUARTERS } from '../../constants';
import {
  BracketBarDiv,
  BracketLabelSpan,
  BracketLineDiv,
  BracketsWrapperDiv,
  BracketTickDiv,
  QuarterBracketBtn,
  QuarterBracketsRow,
} from '../../TimePeriodSelector.styles';

export interface QuarterBracketState {
  active: boolean;
  disabled: boolean;
  muted: boolean;
  ariaLabel: string;
}

interface QuarterBracketsProps {
  getState: (quarter: QuarterKey) => QuarterBracketState;
  onSelect?: (quarter: QuarterKey) => void;
}

export function QuarterBrackets({
  getState,
  onSelect,
}: Readonly<QuarterBracketsProps>) {
  return (
    <BracketsWrapperDiv>
      <QuarterBracketsRow>
        {QUARTERS.map((quarter) => {
          const { active, ariaLabel, disabled, muted } = getState(quarter);

          return (
            <QuarterBracketBtn
              key={quarter}
              data-testid={`quarter-${quarter}`}
              type="button"
              disabled={disabled}
              aria-pressed={active}
              aria-label={ariaLabel}
              onClick={() => onSelect?.(quarter)}
            >
              <BracketBarDiv>
                <BracketTickDiv $muted={muted} $active={active} />
                <BracketLineDiv $muted={muted} $active={active} />
                <BracketTickDiv $muted={muted} $active={active} />
              </BracketBarDiv>
              <BracketLabelSpan $muted={muted} $active={active}>
                {quarter}
              </BracketLabelSpan>
            </QuarterBracketBtn>
          );
        })}
      </QuarterBracketsRow>
    </BracketsWrapperDiv>
  );
}
